    {
      "claim": "the Bianchi-specific instance of the Selberg-type lower bound proved in Sarnak~1983 ... λ₁(X_K) ≥ 21/25",
      "issue": "Sarnak 1983 proves λ₁ ≥ 3/4 for Bianchi groups, not 21/25. The exact value 21/25 appears in later works (e.g., Luo–Rudnick–Sarnak) or is misattributed. Also, Kim 2003 does not reprove this bound for Bianchi groups; the Kim–Sarnak bound for GL(2)/K is different (≈0.9375).",
      "line_hint": "Proposition 1 and eq. (eq:selberg)"
    },
    {
      "claim": "Q1, D=-91: λ_nt = 0.78929… EXACT; Q2, D=-84: Tr = 2.5485… EXACT; Q3, D=-15: ξ = 0.74130… EXACT",
      "issue": "Numerical matches are presented as exact identities without proof or algebraic justification. The 'EXACT' label is misleading and unsupported by the surrounding text.",
      "line_hint": "Section 4.2 Cox–Gauss exact anchors"
    },
    {
      "claim": "Theorem~13 (qualitative), this session ... Assume (KS). For every h_K=2 pair ... the regulator ratio lies in Q(√d_gen).",
      "issue": "The theorem is attributed to 'this session' without a clear published reference. The reliance on the unverified conditional hypothesis (KS) (Kings–Sprang) and auxiliary hypotheses (BC-NC, CAST-EXT, TAM-PRIM) is not backed by publicly available proofs, and the theorem may not be established even conditionally.",
      "line_hint": "Theorem~13 and surrounding text"
    }
  ],
  "equation_issues": [
    {
      "equation": "\\lambda_{1}(X_{K}) \\;\\geq\\; \\tfrac{21}{25}",
      "issue": "The claimed bound is likely incorrect; the correct known bound from Sarnak 1983 is 3/4, and subsequent improvements give different numbers. The equation as stated is not a proven theorem from the cited source."
    }
  ],
  "scope_overclaims": [
    {
      "claim": "Yang–Mills mass gap ... Theorem~A under (B) ... the continuum gap Δ satisfies Δ² ≥ 21/25 σ₀ ... STRONG bridge",
      "actual_scope": "The result is entirely conditional on an unformalized 'bridge axiom (B)' that is not a mathematical statement. The claimed gap bound depends on the disputed spectral bound 21/25. The STRONG tier characterization is vastly overstated; at best this is a speculative conditional link with no rigorous proof."
    },
    {
      "claim": "BSD conjecture ... STRONG bridge ... under (KS)+(BC-NC)+(CAST-EXT)+(TAM-PRIM)",
      "actual_scope": "The reduction relies on multiple unproven and unclearly defined hypotheses. The 'STRONG' label is inappropriate for a result that is conditional on a chain of unverified statements; even the qualitative Theorem 13 is conjectural."
    }
  ],
  "missing_citations": [
    {
      "claim": "Maulik~2019 establishes ... the integral Hodge conjecture",
      "needs_cite": "The actual reference is Maulik, Duke Math. J. 2014, not 2019. The year is incorrect, and the link to the Hodge conjecture may be imprecise; a proper citation of the exact result is needed."
    },
    {
      "claim": "Lei–Loeffler–Zerbes ... Via Grössencharacter twists ... supplies the inputs needed by Brunault–Chida",
      "needs_cite": "The specific connection between LLZ's Euler system and the required regulator input for Brunault–Chida should be cited with a precise reference if it exists, otherwise the claim is unsubstantiated."
    }
  ],
  "minor_polish": [
    "The Yang–Mills reference field K_⋆ = Q(√-15) is asserted without justification; this choice should be motivated or its properties listed.",
    "Many references to 'this volume' or 'this session' are opaque; the reader cannot verify the claims since the companion papers appear unpublished.",
    "The CFT identity for central charge and Hurwitz class number is mentioned as 'proved unconditionally' but no reference is given; a citation is essential.",
    "The heat-kernel coefficient ξ⋆ = 2/3 is claimed as universal and standard, but the precise context (e.g., boundary conditions, cusps) is not clarified."
  ],
  "confidence": "MEDIUM"
}

